

// Based on public.carros
export type Vehicle = {
  id: number;
  created_at: string;
  data_proxima_manutencao?: string | null;
  data_ultima_manutencao?: string | null;
  foto_carro?: string | null;
  marca: string | null;
  modelo: string | null;
  placa: string | null;
  proxima_manutencao?: number | null;
  quilometragem: number;
  ultima_manutencao?: number | null;
  tecnico_atual?: string | null; // This is a UUID from membros table
  displayname_tecnico?: string | null;
};

// For creating a new vehicle, omits fields generated by db
export type NewVehicle = Omit<Vehicle, 'id' | 'created_at' | 'tecnico_atual' | 'foto_carro'> & {
    data_ultima_manutencao?: string;
    data_proxima_manutencao?: string;
};


// Based on public.membros
export type Technician = {
  id: number;
  uuid: string;
  created_at: string;
  cargo: string;
  carro_atual: string;
  display_name: string;
  email: string;
  online: string;
  telefone: string;
  foto_perfil: string;
  ativo: boolean;
  aprovado: boolean;
  ban?: boolean | null;
  ban_motivo?: string | null;
};

// For creating a new technician
export type NewTechnician = {
    uuid: string;
    display_name: string;
    email: string;
    cargo: string;
    telefone: string;
    ativo: boolean;
    aprovado: boolean;
    online: string;
};


// Based on public.registros
export type DailyRecord = {
  id: number;
  created_at: string;
  datahora: string;
  registro_motivo: 'Abastecimento' | 'Expediente' | 'Manutenção';
  tecnico_nome: string;
  carroutilizado: string;
  placa_carro: string;
  km_inicial: number;
  km_final?: number;
  somar_km?: number;
  inicio_expediente?: string;
  final_expediente?: string;
  abastecido?: number; // Liters
  gasto?: number; // Cost
  local_de_abastecimento?: string;
  comprovante_gasolina?: string;
  observacao?: string;
  tecnicoresponsavel?: string | null;
  pago?: boolean;
};

// Based on public.atividades_recentes
export type RecentActivity = {
  id: number;
  created_at: string;
  status: string;
  objetivo: string;
  descricao: string;
  tecnico: string; // This is a UUID, should probably join with membros
};

// Based on public.atualiza_app
export type AppVersion = {
  id: number;
  created_at: string;
  apkUrl: string;
  apkFileName: string;
  packageName: string;
  appversion: string;
};

// Based on public.pagamentos
export type Payment = {
    id?: number;
    comprovante_pagamento?: string;
    motivo?: string;
    nomepagamento?: string;
    pagamentofeito?: boolean;
    valorapagar?: number;
    created_at?: string;
    tecnico?: string; // UUID of user who made the payment
    comprovantes_abastecimentos?: string[] | null;
    valores_abastecidos?: number[] | null;
};

